    "status": "Publicar",
    "tituloSEO": "Análise Crítica de Terceirizado, um trabalhador brasileiro",
    "descricaoSEO": "TERCEIRIZADO, um trabalhador brasileiro. MAIOR, Jorge Luiz Souto. São Paulo. Faculdade de Direito da USP - Universidade de São Paulo, 2014.",
    "generoEditorial": "Análise",
